top_frequent_bought_tickers = Tickers.CALCULATE(
    ticker_symbol = symbol,
    num_buy_transactions = COUNT(
        transactions_of.WHERE(
            (transaction_type == "buy") & (date_time >= DATETIME('now', '-10 days'))
        )
    )
).WHERE(num_buy_transactions > 0).TOP_K(2, by=num_buy_transactions.DESC())

result = Broker.CALCULATE(
    number_of_customers=COUNT(
        Customers.WHERE(
            (
                STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')
            ) & ENDSWITH(LOWER(state), 'a')
        )
    )
)

distinct_buy_customer_ids = Customers.WHERE(
    HAS(transactions_made.WHERE(transaction_type == 'buy')) == 1
).CALCULATE(
    customer_id=_id
)

distinct_ticker_ids_after_date = DailyPrices.WHERE(date >= "2023-04-01").PARTITION(name="unique_tickers_by_id", by=(ticker_id)).CALCULATE(
    ticker_id=ticker_id
)

lowest_vti_close_price_past_7_days = Tickers.WHERE(symbol == "VTI").CALCULATE(
    min_close_price=MIN(historical_prices.WHERE(DATEDIFF("days", date, DATETIME('now')) <= 6).close)
)

result = Broker.CALCULATE(
    num_transactions_by_recent_customers = COUNT(
        Customers.WHERE(
            DATEDIFF("days", join_date, DATETIME('now')) <= 70
        ).transactions_made
    )
)

sales_by_model_with_m5_vin = Dealership.Cars.WHERE(
    LIKE(UPPER(vin_number), '%M5%')  # Filter cars where VIN contains 'M5' (case-insensitive)
).PARTITION(
    name="car_model_group", by=(make, model)  # Group by car make and model
).CALCULATE(
    car_make=make,
    car_model=model,
    number_of_sales=COUNT(Cars.sale_records)  # Count sales for each make/model group
)

result = Dealership.CALCULATE(
    avg_days_sale_to_payment=ROUND(
        AVG(
            Dealership.PaymentsReceived.CALCULATE(
                days_difference=DATEDIFF("days", sale_record.sale_date, payment_date)
            ).days_difference
        ),
        2
    )
)

total_sales_count_last_7_days = Dealership.CALCULATE(
    TSC=COUNT(Sales.WHERE(DATEDIFF("days", sale_date, 'now') < 7))
)

salespersons_with_cash_payments = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(payment_method == 'Cash')) == 1
).CALCULATE(
    salesperson_id=_id
)

top_states_by_revenue = Customers.WHERE(
    HAS(car_purchases) == 1  # Consider only customers who have made purchases
).PARTITION(
    name="state_sales_summary", by=(state)  # Group customers by state
).CALCULATE(
    state_name=state,  # Select the state name
    num_unique_customers=NDISTINCT(Customers._id),  # Count unique customers in this state who made purchases
    total_revenue_val=SUM(Customers.car_purchases.sale_price)  # Calculate total revenue from sales in this state
).TOP_K(
    5, by=total_revenue_val.DESC()  # Select the top 5 states by total revenue
)

top_car_models_by_revenue = Cars.WHERE(
    HAS(sale_records) == 1  # Consider only cars that have at least one sale record
).PARTITION(
    name="car_model_group", by=(make, model)  # Group cars by make and model
).CALCULATE(
    make=make,  # Select the make from the partition key
    model=model,  # Select the model from the partition key
    total_revenue=SUM(Cars.sale_records.sale_price),  # Calculate total revenue for this car model
    total_sales=COUNT(Cars.sale_records)  # Calculate total number of sales for this car model
).TOP_K(
    5, by=total_revenue.DESC()  # Select the top 5 models by total revenue
)

weekend_payments_to_utility_company = Dealership.PaymentsMade.WHERE(
    (vendor_name == "Utility Company") &
    ISIN(DAYOFWEEK(payment_date), (6, 7))  # Assuming Saturday=6 and Sunday=7
).CALCULATE(
    num_payments=COUNT(PaymentsMade.key)
)

# If the output needs to be just the number, and the previous query returns a collection with one row and one column:
# We can use the high-level collection to calculate the count directly.
number_of_weekend_payments = Dealership.CALCULATE(
    count_payments=COUNT(
        PaymentsMade.WHERE(
            (vendor_name == "Utility Company") &
            ISIN(DAYOFWEEK(payment_date), (6, 7)) # Assuming Saturday=6 and Sunday=7
        )
    )
)

average_ddd_per_drug = Drugs.CALCULATE(
    drug_name_output = drug_name,
    average_ddd_output = AVG(
        treatments_used_in.WHERE(
            (end_dt != None) & (DATEDIFF("days", start_dt, end_dt) > 0)
        ).CALCULATE(
            # Calculate DDD for each individual treatment
            ddd_value_for_treatment = tot_drug_amt / DATEDIFF("days", start_dt, end_dt)
        ).ddd_value_for_treatment # Access the calculated DDD value for the AVG function
    )
)

patients_with_gmail_or_yahoo = DermTreatment.CALCULATE(
    num_patients=COUNT(
        Patients.WHERE(
            (ENDSWITH(email, "@gmail.com")) | (ENDSWITH(email, "@yahoo.com"))
        )
    )
)

count_patients_psoriasis_biologic = DermTreatment.CALCULATE(
    num_matching_patients=COUNT(
        Patients.WHERE(
            HAS(
                treatments_received.WHERE(
                    (diagnosis.diag_name == 'Psoriasis vulgaris') & 
                    (drug.drug_type == 'biologic')
                )
            ) == 1
        )
    )
)

result = DermTreatment.CALCULATE(
    average_patient_weight=AVG(
        Drugs.WHERE(drug_name == 'Drugalin').treatments_used_in.patient.weight_kg
    )
)

male_patients_caw = DermTreatment.CALCULATE(
    caw_male_patients=AVG(Patients.WHERE(gender == 'Male').weight_kg)
)

result = DermTreatment.CALCULATE(
    PIC=COUNT(Patients.WHERE((gender == "Female") & (ins_type == "Private")))
)

result = Doctors.WHERE(
    HAS(prescribed_treatments.WHERE(drug.drug_type == "biologic")) == 1
).PARTITION(
    name="distinct_states", by=(loc_state)
).CALCULATE(
    state_name=loc_state
)

average_age_of_patients = DermTreatment.CALCULATE(
    avg_patient_age=ROUND(
        AVG(
            Patients.WHERE((gender == "Male") & (ins_type == "Private"))
            .CALCULATE(
                age_in_years=DATEDIFF("years", date_of_birth, DATETIME('now'))
            )
            .age_in_years
        ),
        0
    )
)

user_marketing_opt_in_details = Users.CALCULATE(
    user_id_val=uid,
    marketing_opt_in_preference=setting_snapshots.WHERE(
        RANKING(by=snapshot_date.DESC(), per="Users", allow_ties=False) == 1
    ).SINGULAR().marketing_opt_in
)

result = Users.CALCULATE(
    user_id_col=uid,
    total_user_session_duration=SUM(
        sessions.WHERE(
            (session_start_ts >= "2023-06-01T00:00:00.000") & (session_start_ts < "2023-06-08T00:00:00.000")
        ).CALCULATE(
            individual_session_duration_seconds=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).individual_session_duration_seconds
    )
).WHERE(
    total_user_session_duration > 0
).ORDER_BY(
    total_user_session_duration.DESC()
)

tuc_past_month = Ewallet.CALCULATE(
    total_sessions_count = COUNT(
        UserSessions.WHERE(
            (session_start_ts >= DATETIME('now', '-1 month')) & (session_start_ts <= DATETIME('now'))
        )
    )
)

users_with_unread_promotional_notifications = Users.WHERE(
    (LOWER(country) == 'us') &
    (HAS(notifications.WHERE((notification_type == 'promotional') & (status == 'unread'))) == 1)
).CALCULATE(
    user_name_val=username,
    num_unread_promo_notifications=COUNT(
        notifications.WHERE((notification_type == 'promotional') & (status == 'unread'))
    )
)

distinct_users_with_transaction_notifications = Users.WHERE(
    HAS(notifications.WHERE(type == "transaction")) == 1
).CALCULATE(
    user_id_col=uid
)

result = Ewallet.CALCULATE(
    median_retail_merchant_balance_today=MEDIAN(
        Merchants.WHERE(
            (status == "active") & CONTAINS(LOWER(category), "retail")
        ).balances.WHERE(
            DATETIME(updated_at, 'start of day') == DATETIME('now', 'start of day')
        ).balance
    )
)
